import java.util.Scanner;

public class Main {
    static final long MOD_CONST = 1000000007;
    static long number_input;
    static int digit_count, base_number, total_result, position_index, digits_array[] = new int[110];

    static void add_mod(int[] x, int y, int m) {
        x[0] += y;
        if (x[0] >= m) x[0] -= m;
    }

    static class Matrix {
        int[][] mat = new int[35][35];

        Matrix() {
            for (int i = 0; i < 35; i++) {
                for (int j = 0; j < 35; j++) {
                    mat[i][j] = 0;
                }
            }
        }

        Matrix multiply(Matrix other) {
            Matrix res = new Matrix();
            for (int k = 0; k <= base_number; k++) {
                for (int i = 0; i <= base_number; i++) {
                    if (this.mat[i][k] != 0) {
                        for (int j = 0; j <= base_number; j++) {
                            if (other.mat[k][j] != 0) {
                                long temp = (1L * this.mat[i][k] * other.mat[k][j]) + res.mat[i][j];
                                res.mat[i][j] = (int) (temp % MOD_CONST);
                            }
                        }
                    }
                }
            }
            return res;
        }
    }

    static Matrix[][] sMatArr = new Matrix[75][35];
    static Matrix[][] prefixMatArr = new Matrix[75][35];
    static Matrix[][] suffixMatArr = new Matrix[75][35];

    static void parseNumber(long number) {
        long temp = number;
        digit_count = 0;
        while (temp != 0) {
            digits_array[++digit_count] = (int) (temp % base_number);
            temp /= base_number;
        }
        // Reverse the digits_array from 1 to digit_count
        for (int i = 1; i <= digit_count / 2; i++) {
            int tmp = digits_array[i];
            digits_array[i] = digits_array[digit_count - i + 1];
            digits_array[digit_count - i + 1] = tmp;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        number_input = sc.nextLong();
        base_number = sc.nextInt();

        parseNumber(number_input);

        // Initialize sMatArr[0][i]
        for (int i = 0; i < base_number; i++) {
            sMatArr[0][i] = new Matrix();
            for (int j = 0; j <= base_number; j++) {
                sMatArr[0][i].mat[j][j] = 1;
                sMatArr[0][i].mat[i][j] = 1;
            }
        }

        for (int i = 1; i <= digit_count; i++) {
            int idx = digit_count - i;
            for (int j = 0; j < base_number; j++) {
                prefixMatArr[idx][0] = sMatArr[idx][0];
                suffixMatArr[idx][base_number - 1] = sMatArr[idx][base_number - 1];

                for (int k = 1; k < base_number; k++) {
                    prefixMatArr[idx][k] = prefixMatArr[idx][k - 1].multiply(sMatArr[idx][k]);
                }
                for (int k = base_number - 2; k >= 0; k--) {
                    suffixMatArr[idx][k] = sMatArr[idx][k].multiply(suffixMatArr[idx][k + 1]);
                }
                for (int j = 0; j < base_number; j++) {
                    if (j != 0) {
                        sMatArr[idx][j] = suffixMatArr[idx][j].multiply(prefixMatArr[idx][j - 1]);
                    } else {
                        sMatArr[idx][j] = suffixMatArr[idx][j];
                    }
                }
            }
        }

        // Initialize answerMatrix
        Matrix answerMatrix = new Matrix();
        for (int i = 0; i <= base_number; i++) {
            answerMatrix.mat[i][i] = 1;
        }

        position_index = 0;
        for (int i = 1; i <= digit_count; i++) {
            int digit = digits_array[i];
            if (digit != 0) {
                int idx = digit_count - i;
                if (position_index + digit - 1 >= base_number) {
                    for (int j = position_index; j < base_number; j++) {
                        answerMatrix = answerMatrix.multiply(sMatArr[idx][j]);
                    }
                    for (int j = 0; j <= (position_index + digit - 1) - base_number; j++) {
                        answerMatrix = answerMatrix.multiply(sMatArr[idx][j]);
                    }
                } else {
                    for (int j = position_index; j <= position_index + digit - 1; j++) {
                        answerMatrix = answerMatrix.multiply(sMatArr[idx][j]);
                    }
                }
                add_mod(new int[]{position_index}, digit, base_number);
            }
        }

        total_result = 0;
        for (int i = 0; i <= base_number; i++) {
            total_result += answerMatrix.mat[i][base_number];
        }
        total_result %= MOD_CONST;

        System.out.println(total_result);
        sc.close();
    }
}
